files.content:
.calendar {
  width: 296px;
  user-select: none;
}

.caption {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
  margin-bottom: 8px;
}

.captionLabel {
  flex: 1;
  text-align: center;
  font-size: 14px;
  font-weight: 700;
  color: var(--ink-heading);
}

.navGroup {
  display: flex;
  gap: 2px;
}

/* ── Dropdown caption ───────────────────────────────────────────────────
   the reference customer form puts Month and Year selects in the caption. Here
   they are quiet text buttons with a chevron, so the caption still reads as
   a heading ("September 2026") until pointed at. */

.captionButtons {
  display: flex;
  flex: 1;
  justify-content: center;
  gap: 2px;
  min-width: 0;
}

.captionButton {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  height: 30px;
  padding: 0 6px 0 9px;
  border: 0;
  border-radius: var(--r-xs);
  background: transparent;
  font-family: var(--font-body);
  font-size: 14px;
  font-weight: 700;
  font-variant-numeric: tabular-nums;
  color: var(--ink-heading);
  white-space: nowrap;
  transition:
    background-color var(--dur) var(--ease),
    color var(--dur) var(--ease),
    box-shadow var(--dur) var(--ease);
}

.captionChevron {
  color: var(--ink-muted);
  transition:
    transform var(--dur) var(--ease),
    color var(--dur) var(--ease);
}

.captionButton:hover {
  background: var(--wash-hover);
  box-shadow: inset 0 0 0 1px var(--line-brand);
  color: var(--ink-brand);
}

.captionButton:hover .captionChevron,
.captionButton[aria-expanded="true"] .captionChevron {
  color: var(--ink-brand);
}

.captionButton:active {
  background: var(--wash-strong);
}

.captionButton[aria-expanded="true"] {
  background: var(--wash-active);
  box-shadow: inset 0 0 0 1px var(--line-brand-strong);
  color: var(--ink-brand);
}

.captionButton[aria-expanded="true"] .captionChevron {
  transform: rotate(180deg);
}

.captionButton:focus-visible {
  outline: none;
  box-shadow: var(--focus-ring);
}

/* ── Quick pickers ──────────────────────────────────────────────────────
   Same footprint as the day grid (weekday row + six weeks), so opening one
   never resizes the popup. */

.picker {
  display: grid;
  gap: 4px;
  height: 268px;
}

.monthPicker {
  grid-template-columns: repeat(3, 1fr);
  grid-auto-rows: 1fr;
}

.yearPicker {
  grid-template-columns: repeat(4, 1fr);
  grid-auto-rows: 38px;
  align-content: start;
  overflow-y: auto;
  overscroll-behavior: contain;
  /* Room for the focus ring on the outer options. */
  padding: 3px;
  margin: -3px;
  scrollbar-width: thin;
}

.pickerOption {
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 0;
  border: 0;
  border-radius: var(--r-xs);
  background: transparent;
  font-family: var(--font-body);
  font-size: 13.5px;
  font-weight: 600;
  font-variant-numeric: tabular-nums;
  color: var(--ink-body);
  transition:
    background-color var(--dur-fast) var(--ease),
    color var(--dur-fast) var(--ease);
}

.pickerOption:hover:not(.pickerSelected):not(.pickerBlocked) {
  background: var(--wash-active);
  color: var(--ink-brand);
}

.pickerOption:active:not(.pickerBlocked) {
  background: var(--wash-strong);
}

.pickerOption:focus-visible {
  outline: none;
  box-shadow: var(--focus-ring);
}

/* This year, as today is in the grid: an inset ring, not a fill. */
.pickerCurrent {
  box-shadow: inset 0 0 0 2px var(--brand);
  color: var(--ink-brand);
  font-weight: 700;
}

.pickerSelected {
  background: var(--brand-gradient);
  color: var(--ink-inverse);
  font-weight: 700;
  box-shadow: var(--glow-sm);
}

.pickerSelected:focus-visible {
  box-shadow: var(--focus-ring), var(--glow-sm);
}

.pickerBlocked {
  cursor: not-allowed;
  color: var(--ink-disabled);
  text-decoration: line-through;
  text-decoration-color: rgba(var(--rgb-brand-deep), 0.25);
}

/* the reference design: 28px glass-outline nav, faint until hovered. */
.nav {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 28px;
  height: 28px;
  padding: 0;
  border: 0;
  border-radius: var(--r-xs);
  background: transparent;
  box-shadow: inset 0 0 0 1px var(--line);
  color: var(--ink-muted);
  transition:
    color var(--dur) var(--ease),
    box-shadow var(--dur) var(--ease),
    background-color var(--dur) var(--ease);
}

.nav:hover:not(:disabled) {
  color: var(--ink-brand);
  background: var(--wash-hover);
  box-shadow: inset 0 0 0 1px var(--line-brand-strong);
}

.nav:focus-visible {
  outline: none;
  box-shadow: var(--focus-ring);
}

.nav:disabled {
  cursor: not-allowed;
  color: var(--ink-disabled);
  opacity: 0.5;
}

.grid {
  display: flex;
  flex-direction: column;
  gap: 2px;
}

.row {
  display: grid;
  grid-template-columns: repeat(7, 1fr);
  gap: 2px;
}

.head {
  display: flex;
  align-items: center;
  justify-content: center;
  height: 28px;
  font-size: var(--text-micro);
  font-weight: 700;
  letter-spacing: 0.04em;
  text-transform: uppercase;
  color: var(--ink-muted);
}

.cell {
  display: flex;
}

/* A neighbouring month's day: an empty slot that holds the grid, with
   the same height as a day so the six rows never change size. */
.empty {
  min-height: 38px;
}

.day {
  width: 100%;
  height: 38px;
  padding: 0;
  border: 0;
  border-radius: var(--r-xs);
  background: transparent;
  font-size: 13.5px;
  font-variant-numeric: tabular-nums;
  color: var(--ink-body);
  transition:
    background-color var(--dur-fast) var(--ease),
    color var(--dur-fast) var(--ease);
}

.day:hover:not(.disabled):not(.selected) {
  background: var(--wash-active);
  color: var(--ink-brand);
}

.day:focus-visible {
  outline: none;
  box-shadow: var(--focus-ring);
}

.today {
  box-shadow: inset 0 0 0 2px var(--brand);
  color: var(--ink-brand);
  font-weight: 700;
}

.selected {
  background: var(--brand-gradient);
  color: var(--ink-inverse);
  font-weight: 700;
  box-shadow: var(--glow-sm);
}

.selected:focus-visible {
  box-shadow: var(--focus-ring), var(--glow-sm);
}

.disabled {
  cursor: not-allowed;
  color: var(--ink-disabled);
  text-decoration: line-through;
  text-decoration-color: rgba(var(--rgb-brand-deep), 0.25);
}

/* ── Months side by side ───────────────────────────────────────────────── */

.multi {
  display: flex;
  gap: 28px;
  width: auto;
}

.multi .month {
  width: 296px;
}

/* Same footprint as a nav group (2 × 28 + 2), so both captions centre. */
.navSpacer {
  width: 58px;
  flex-shrink: 0;
}

/* ── Range ──────────────────────────────────────────────────────────────
   the reference §4.11, recoloured. The band lives on the cell, the ends on the
   day: start and end carry the gradient with only their outer corners
   rounded, and the band runs half-way under each so it meets them flush.
   Columns close up so the band reads as one strip, not stripes. */

.range .row {
  column-gap: 0;
}

.cell {
  --band: var(--wash-active);
}

/* While only the start is picked the band is a proposal: lighter. */
.bandPreview {
  --band: var(--wash-subtle);
}

.bandMiddle {
  background: var(--band);
}

.bandStart {
  background: linear-gradient(to right, transparent 50%, var(--band) 50%);
}

.bandEnd {
  background: linear-gradient(to left, transparent 50%, var(--band) 50%);
}

/* The band turns its corners at the week's edges rather than running off. */
.bandMiddle:first-child {
  border-radius: var(--r-xs) 0 0 var(--r-xs);
}

.bandMiddle:last-child {
  border-radius: 0 var(--r-xs) var(--r-xs) 0;
}

/* Where the band crosses into another month it is cut square, even on a
   Monday or Sunday: the range carries on in the next pane (or the next page),
   so a rounded corner there would read as its end. Only the range's own ends
   round. Same specificity as the week-edge rules above and later, so it wins. */
.bandMiddle.bandContinuesIn {
  border-top-left-radius: 0;
  border-bottom-left-radius: 0;
}

.bandMiddle.bandContinuesOut {
  border-top-right-radius: 0;
  border-bottom-right-radius: 0;
}

.rangeStart {
  border-radius: var(--r-xs) 0 0 var(--r-xs);
}

.rangeEnd {
  border-radius: 0 var(--r-xs) var(--r-xs) 0;
}

.rangeMiddle {
  border-radius: 0;
  color: var(--ink-brand);
}

.day.rangeMiddle:hover:not(.disabled) {
  background: var(--wash-active);
}

/* Provisional end under the pointer: outlined, not filled, until clicked. */
.previewEnd {
  border-radius: 0 var(--r-xs) var(--r-xs) 0;
  background: var(--wash-active);
  box-shadow: inset 0 0 0 1.5px var(--line-brand-strong);
  color: var(--ink-brand);
  font-weight: 700;
}

.previewEnd:focus-visible {
  box-shadow: var(--focus-ring);
}

"use client";

import { useEffect, useId, useRef, useState, type KeyboardEvent } from "react";
import { cx } from "../_internal/cx";
import {
  IconChevronDown,
  IconChevronLeft,
  IconChevronRight,
  IconChevronsLeft,
  IconChevronsRight,
} from "../Icon/Icon";
import {
  addDays,
  addMonths,
  compareIso,
  daysInMonth,
  formatDateLong,
  MONTH_NAMES,
  MONTH_SHORT,
  monthLabel,
  parseIso,
  toIso,
  todayIso,
  weekdayIndex,
  WEEKDAY_NAMES,
  WEEKDAY_SHORT,
  type IsoDate,
} from "./date-utils";
import styles from "./Calendar.module.css";

/** An inclusive span of days. Either end may be open while it is being picked. */
export type DateRange = { start: IsoDate | null; end: IsoDate | null };

/**
 * The range after picking a day: the first pick starts it, the second ends it,
 * and a day before the start (or any pick once both ends are set) starts over.
 */
export function nextRange(range: DateRange, iso: IsoDate): DateRange {
  if (!range.start || range.end) return { start: iso, end: null };
  if (compareIso(iso, range.start) < 0) return { start: iso, end: null };
  return { start: range.start, end: iso };
}

type CalendarBaseProps = {
  /** Days that cannot be picked. Still focusable, so keyboard users can pass over them. */
  isDateDisabled?: (date: IsoDate) => boolean;
  min?: IsoDate;
  max?: IsoDate;
  /** Month shown first when there is no value. Defaults to today's month. */
  defaultMonth?: IsoDate;
  /** Moves focus into the grid on mount (used by DateField's popup). */
  autoFocus?: boolean;
  /** Months side by side. Navigation moves them together. */
  numberOfMonths?: 1 | 2;
  /**
   * label: the month and year as a heading, with month and year arrows.
   * dropdown: Month ▾ and Year ▾ buttons that open quick pickers, for dates
   * years away such as a date of birth (a sign-up form). Month
   * arrows stay. Two-month calendars always use labels.
   */
  captionLayout?: "label" | "dropdown";
  /**
   * First and last years the Year picker lists (dropdown only). Default to
   * min's and max's years, else 100 years back and 10 on. They also bound the
   * arrows and keyboard paging, so the grid never shows a year the picker lacks.
   */
  fromYear?: number;
  toYear?: number;
  className?: string;
};

type SingleProps = {
  value: IsoDate | null;
  onChange: (value: IsoDate) => void;
  range?: never;
  onRangeChange?: never;
};

type RangeProps = {
  /** Range mode. After a start is picked, hovering or arrowing previews the range. */
  range: DateRange;
  onRangeChange: (range: DateRange) => void;
  value?: never;
  onChange?: never;
};

export type CalendarProps = CalendarBaseProps & (SingleProps | RangeProps);

type Picker = "month" | "year";

const monthIndex = (iso: IsoDate) => {
  const { y, m } = parseIso(iso);
  return y * 12 + (m - 1);
};

const later = (a: IsoDate | undefined, b: IsoDate) => (a && compareIso(a, b) > 0 ? a : b);
const earlier = (a: IsoDate | undefined, b: IsoDate) => (a && compareIso(a, b) < 0 ? a : b);

// Columns in each quick picker; arrow up and down move by a row.
const MONTH_COLS = 3;
const YEAR_COLS = 4;

/**
 * Month grid, Monday first. Arrow keys move by day and week, Home/End to the
 * week's ends, PageUp/PageDown by month (Shift for year), Enter or Space picks.
 * Only the focused day is in the tab order (roving tabindex).
 *
 * With captionLayout="dropdown" the caption's Month and Year buttons swap the
 * grid for a month grid or a year list, in the same footprint so the popup
 * never jumps. Arrows move through the picker, Enter picks, Esc goes back to
 * the days (and stops there, so an enclosing popup stays open).
 */
export function Calendar({
  value,
  onChange,
  range,
  onRangeChange,
  isDateDisabled,
  min: minProp,
  max: maxProp,
  defaultMonth,
  autoFocus,
  numberOfMonths = 1,
  captionLayout = "label",
  fromYear,
  toYear,
  className,
}: CalendarProps) {
  const idBase = `cal-${useId()}`;
  const [today] = useState(todayIso);
  const count = numberOfMonths;
  const isRange = range !== undefined;
  const dropdown = captionLayout === "dropdown" && count === 1;

  // In dropdown mode the year span is a hard bound too, folded into min/max.
  const thisYear = parseIso(today).y;
  const firstYear = fromYear ?? (minProp ? parseIso(minProp).y : thisYear - 100);
  const lastYear = toYear ?? (maxProp ? parseIso(maxProp).y : thisYear + 10);
  const min = dropdown ? later(minProp, toIso(firstYear, 1, 1)) : minProp;
  const max = dropdown ? earlier(maxProp, toIso(lastYear, 12, 31)) : maxProp;

  const clamp = (iso: IsoDate) => {
    if (min && compareIso(iso, min) < 0) return min;
    if (max && compareIso(iso, max) > 0) return max;
    return iso;
  };

  // Single mode opens on the value. Range mode opens on the range's start,
  // and focuses today when no range is set and today is on screen.
  const [initial] = useState(() => {
    if (!isRange) {
      // Dropdown mode can't show a year outside its list, so it opens within it.
      const wanted = value ?? defaultMonth ?? today;
      const start = dropdown ? clamp(wanted) : wanted;
      return { view: start, focus: start };
    }
    const anchor = range.start ?? range.end;
    const view = anchor ?? defaultMonth ?? today;
    const offset = monthIndex(today) - monthIndex(view);
    return { view, focus: anchor ?? (offset >= 0 && offset < count ? today : view) };
  });
  const [focused, setFocused] = useState<IsoDate>(initial.focus);
  const [view, setView] = useState(() => {
    const { y, m } = parseIso(initial.view);
    return { y, m };
  });
  const [hover, setHover] = useState<IsoDate | null>(null);
  const [picker, setPicker] = useState<Picker | null>(null);
  const rootRef = useRef<HTMLDivElement>(null);
  const pickerRef = useRef<HTMLDivElement>(null);
  const monthButtonRef = useRef<HTMLButtonElement>(null);
  const yearButtonRef = useRef<HTMLButtonElement>(null);
  const moveFocus = useRef(Boolean(autoFocus));

  const outOfRange = (iso: IsoDate) => (min ? compareIso(iso, min) < 0 : false) || (max ? compareIso(iso, max) > 0 : false);
  const unavailable = (iso: IsoDate) => outOfRange(iso) || Boolean(isDateDisabled?.(iso));

  const viewIndex = view.y * 12 + (view.m - 1);
  const isVisibleMonth = (iso: IsoDate) => {
    const i = monthIndex(iso);
    return i >= viewIndex && i < viewIndex + count;
  };

  const goTo = (iso: IsoDate, focus: boolean) => {
    const next = clamp(iso);
    setFocused(next);
    // Page only when the day leaves the visible months, so arrowing across
    // the gap between two months does not jump both panes.
    if (!isVisibleMonth(next)) {
      const lead = monthIndex(next) < viewIndex ? next : addMonths(next, -(count - 1));
      const { y, m } = parseIso(lead);
      setView({ y, m });
    }
    moveFocus.current = focus;
  };

  const shiftMonth = (months: number) => {
    const first = toIso(view.y, view.m, 1);
    const target = addMonths(first, months);
    const { y, m } = parseIso(target);
    setView({ y, m });
    // Keep the focused day in the visible month, clamped to its length.
    setFocused(clamp(addMonths(focused, months)));
    moveFocus.current = false;
  };

  useEffect(() => {
    if (!moveFocus.current) return;
    rootRef.current?.querySelector<HTMLButtonElement>(`[data-date="${focused}"]`)?.focus();
    moveFocus.current = false;
  }, [focused]);

  // A picker opens on the current month or year, scrolled to the middle of
  // the list so the years either side are in reach.
  useEffect(() => {
    if (!picker) return;
    const current = pickerRef.current?.querySelector<HTMLButtonElement>('[aria-selected="true"]');
    if (!current) return;
    current.scrollIntoView({ block: "center" });
    current.focus({ preventScroll: true });
  }, [picker]);

  const pick = (iso: IsoDate) => {
    if (unavailable(iso)) return;
    if (range && onRangeChange) onRangeChange(nextRange(range, iso));
    else onChange?.(iso);
  };

  const onKeyDown = (e: KeyboardEvent<HTMLDivElement>) => {
    const map: Record<string, () => IsoDate> = {
      ArrowLeft: () => addDays(focused, -1),
      ArrowRight: () => addDays(focused, 1),
      ArrowUp: () => addDays(focused, -7),
      ArrowDown: () => addDays(focused, 7),
      Home: () => addDays(focused, -weekdayIndex(focused)),
      End: () => addDays(focused, 6 - weekdayIndex(focused)),
      PageUp: () => addMonths(focused, e.shiftKey ? -12 : -1),
      PageDown: () => addMonths(focused, e.shiftKey ? 12 : 1),
    };
    const fn = map[e.key];
    if (fn) {
      e.preventDefault();
      goTo(fn(), true);
    } else if (e.key === "Enter" || e.key === " ") {
      e.preventDefault();
      pick(focused);
    }
  };

  // ── Quick pickers ───────────────────────────────────────────────────────

  const triggerFor = (which: Picker) => (which === "month" ? monthButtonRef : yearButtonRef);

  const closePicker = (which: Picker) => {
    setPicker(null);
    triggerFor(which).current?.focus();
  };

  /** Moves the view to a month, keeping the focused day's number where it fits. */
  const showMonth = (y: number, m: number, which: Picker) => {
    const { d } = parseIso(focused);
    const target = clamp(toIso(y, m, Math.min(d, daysInMonth(y, m))));
    const shown = parseIso(target);
    setView({ y: shown.y, m: shown.m });
    setFocused(target);
    moveFocus.current = false;
    closePicker(which);
  };

  const monthOutOfBounds = (y: number, m: number) =>
    (min ? compareIso(toIso(y, m, daysInMonth(y, m)), min) < 0 : false) ||
    (max ? compareIso(toIso(y, m, 1), max) > 0 : false);

  const onPickerKeyDown = (e: KeyboardEvent<HTMLDivElement>, which: Picker) => {
    if (e.key === "Escape") {
      e.preventDefault();
      e.stopPropagation();
      closePicker(which);
      return;
    }
    const cols = which === "month" ? MONTH_COLS : YEAR_COLS;
    const options = Array.from(pickerRef.current?.querySelectorAll<HTMLButtonElement>('[role="option"]') ?? []);
    const at = options.indexOf(document.activeElement as HTMLButtonElement);
    if (at === -1) return;
    const step: Record<string, number> = {
      ArrowLeft: -1,
      ArrowRight: 1,
      ArrowUp: -cols,
      ArrowDown: cols,
      PageUp: -cols * 3,
      PageDown: cols * 3,
      Home: -at,
      End: options.length - 1 - at,
    };
    if (!(e.key in step)) return;
    e.preventDefault();
    const next = Math.max(0, Math.min(options.length - 1, at + step[e.key]));
    options[next].focus();
    options[next].scrollIntoView({ block: "nearest" });
  };

  const renderPicker = (which: Picker) => {
    if (which === "month") {
      return (
        <div
          ref={pickerRef}
          role="listbox"
          aria-label={`Month, ${view.y}`}
          className={cx(styles.picker, styles.monthPicker)}
          onKeyDown={(e) => onPickerKeyDown(e, "month")}
        >
          {MONTH_SHORT.map((label, i) => {
            const m = i + 1;
            const selected = m === view.m;
            const blocked = monthOutOfBounds(view.y, m);
            return (
              <button
                key={label}
                type="button"
                role="option"
                aria-selected={selected}
                aria-label={MONTH_NAMES[i]}
                aria-disabled={blocked || undefined}
                tabIndex={selected ? 0 : -1}
                className={cx(styles.pickerOption, selected && styles.pickerSelected, blocked && styles.pickerBlocked)}
                onClick={() => {
                  if (!blocked) showMonth(view.y, m, "month");
                }}
              >
                {label}
              </button>
            );
          })}
        </div>
      );
    }
    const lo = min ? parseIso(min).y : firstYear;
    const hi = max ? parseIso(max).y : lastYear;
    const years = Array.from({ length: Math.max(0, hi - lo + 1) }, (_, i) => lo + i);
    return (
      <div
        ref={pickerRef}
        role="listbox"
        aria-label="Year"
        className={cx(styles.picker, styles.yearPicker)}
        onKeyDown={(e) => onPickerKeyDown(e, "year")}
      >
        {years.map((y) => {
          const selected = y === view.y;
          return (
            <button
              key={y}
              type="button"
              role="option"
              aria-selected={selected}
              tabIndex={selected ? 0 : -1}
              className={cx(styles.pickerOption, selected && styles.pickerSelected, y === thisYear && styles.pickerCurrent)}
              onClick={() => showMonth(y, view.m, "year")}
            >
              {y}
            </button>
          );
        })}
      </div>
    );
  };

  // ── Range band ──────────────────────────────────────────────────────────

  // Range ends. A lone end is treated as the start. While only the start is
  // set, the hovered (or keyboard-focused) day stands in as a provisional end.
  const rangeStart = range ? (range.start ?? range.end) : null;
  const committedEnd = range?.start ? range.end : null;
  const previewEnd =
    isRange && rangeStart && !committedEnd && hover && compareIso(hover, rangeStart) >= 0 ? hover : null;
  const rangeEnd = committedEnd ?? previewEnd;
  const spans = Boolean(rangeStart && rangeEnd && rangeStart !== rangeEnd);

  const firstOfView = toIso(view.y, view.m, 1);
  const canPrevMonth = !min || compareIso(addDays(firstOfView, -1), min) >= 0;
  const canNextMonth = !max || compareIso(addMonths(firstOfView, count), max) <= 0;
  const canPrevYear = !min || compareIso(addDays(addMonths(firstOfView, -11), -1), min) >= 0;
  const canNextYear = !max || compareIso(addMonths(firstOfView, 12 + count - 1), max) <= 0;

  // With a picker open the arrows would page a grid that isn't showing.
  const navLocked = picker !== null;
  const prevNav = (
    <div className={styles.navGroup}>
      {dropdown ? null : (
        <button type="button" className={styles.nav} onClick={() => shiftMonth(-12)} disabled={!canPrevYear} aria-label="Previous year">
          <IconChevronsLeft size={15} />
        </button>
      )}
      <button
        type="button"
        className={styles.nav}
        onClick={() => shiftMonth(-1)}
        disabled={!canPrevMonth || navLocked}
        aria-label="Previous month"
      >
        <IconChevronLeft size={15} />
      </button>
    </div>
  );
  const nextNav = (
    <div className={styles.navGroup}>
      <button
        type="button"
        className={styles.nav}
        onClick={() => shiftMonth(1)}
        disabled={!canNextMonth || navLocked}
        aria-label="Next month"
      >
        <IconChevronRight size={15} />
      </button>
      {dropdown ? null : (
        <button type="button" className={styles.nav} onClick={() => shiftMonth(12)} disabled={!canNextYear} aria-label="Next year">
          <IconChevronsRight size={15} />
        </button>
      )}
    </div>
  );
  // Holds the caption centred in a pane that carries only one nav group.
  const navSpacer = <div className={styles.navSpacer} aria-hidden="true" />;

  const captionButton = (which: Picker, label: string) => (
    <button
      ref={triggerFor(which)}
      type="button"
      className={styles.captionButton}
      aria-haspopup="listbox"
      aria-expanded={picker === which}
      aria-label={`${which === "month" ? "Month" : "Year"}: ${label}. Change`}
      onClick={() => (picker === which ? closePicker(which) : setPicker(which))}
    >
      <span>{label}</span>
      <IconChevronDown size={14} className={styles.captionChevron} />
    </button>
  );

  const renderMonth = (index: number) => {
    const first = addMonths(firstOfView, index);
    const { y, m: month } = parseIso(first);
    const captionId = `${idBase}-${index}`;
    // Six rows from the Monday on or before the 1st, so height never jumps.
    const gridStart = addDays(first, -weekdayIndex(first));
    const weeks = Array.from({ length: 6 }, (_, w) => Array.from({ length: 7 }, (_, d) => addDays(gridStart, w * 7 + d)));

    return (
      <div key={first} className={styles.month}>
        <div className={styles.caption}>
          {index === 0 ? prevNav : navSpacer}
          {dropdown ? (
            <>
              <div className={styles.captionButtons}>
                {captionButton("month", MONTH_NAMES[month - 1])}
                {captionButton("year", String(y))}
              </div>
              <p id={captionId} className="sr-only" aria-live="polite">
                {monthLabel(y, month)}
              </p>
            </>
          ) : (
            <p id={captionId} className={styles.captionLabel} aria-live="polite">
              {monthLabel(y, month)}
            </p>
          )}
          {index === count - 1 ? nextNav : navSpacer}
        </div>

        {dropdown && picker ? (
          renderPicker(picker)
        ) : (
          <div
            role="grid"
            aria-labelledby={captionId}
            aria-multiselectable={isRange || undefined}
            className={styles.grid}
            onKeyDown={onKeyDown}
          >
            <div role="row" className={styles.row}>
              {WEEKDAY_SHORT.map((d, i) => (
                <span key={d} role="columnheader" aria-label={WEEKDAY_NAMES[i]} className={styles.head}>
                  {d}
                </span>
              ))}
            </div>
            {weeks.map((week) => (
              <div role="row" key={week[0]} className={styles.row}>
                {week.map((iso) => {
                  const { m, d } = parseIso(iso);
                  // Days from the neighbouring months are not drawn: the grid shows one month, and the empty cells
                  // keep every date under its weekday. Arrowing or paging past
                  // the month's edge still works; it turns the page.
                  if (m !== month) {
                    return <span role="gridcell" key={iso} className={cx(styles.cell, styles.empty)} />;
                  }
                  const lastOfMonth = parseIso(addDays(iso, 1)).m !== month;

                  const isDisabled = unavailable(iso);
                  const isStart = isRange && iso === rangeStart;
                  const isEnd = isRange && iso === rangeEnd;
                  const inMiddle =
                    spans && compareIso(iso, rangeStart as IsoDate) > 0 && compareIso(iso, rangeEnd as IsoDate) < 0;
                  const isPreviewEnd = isEnd && !committedEnd && !isStart;
                  const isSelected = isRange
                    ? isStart || (Boolean(committedEnd) && (isEnd || inMiddle))
                    : iso === value;

                  return (
                    <span
                      role="gridcell"
                      key={iso}
                      aria-selected={isSelected || undefined}
                      className={cx(
                        styles.cell,
                        spans && isStart && styles.bandStart,
                        spans && isEnd && styles.bandEnd,
                        inMiddle && styles.bandMiddle,
                        // A band that carries on from the previous month, or
                        // into the next, is cut square at the month's edge: the
                        // range hasn't ended there. Only
                        // the range's real ends are rounded.
                        inMiddle && d === 1 && styles.bandContinuesIn,
                        inMiddle && lastOfMonth && styles.bandContinuesOut,
                        isRange && !committedEnd && styles.bandPreview,
                      )}
                    >
                      <button
                        type="button"
                        data-date={iso}
                        tabIndex={iso === focused ? 0 : -1}
                        aria-label={formatDateLong(iso)}
                        aria-current={iso === today ? "date" : undefined}
                        aria-disabled={isDisabled || undefined}
                        onClick={() => {
                          setFocused(iso);
                          pick(iso);
                        }}
                        onMouseEnter={isRange && !isDisabled ? () => setHover(iso) : undefined}
                        onFocus={isRange ? () => setHover(iso) : undefined}
                        className={cx(
                          styles.day,
                          iso === today && styles.today,
                          (isStart || (isEnd && !isPreviewEnd) || (!isRange && isSelected)) && styles.selected,
                          spans && isStart && styles.rangeStart,
                          spans && isEnd && !isPreviewEnd && styles.rangeEnd,
                          isPreviewEnd && styles.previewEnd,
                          inMiddle && styles.rangeMiddle,
                          isDisabled && styles.disabled,
                        )}
                      >
                        {d}
                      </button>
                    </span>
                  );
                })}
              </div>
            ))}
          </div>
        )}
      </div>
    );
  };

  return (
    <div data-slot="calendar"
      ref={rootRef}
      className={cx(styles.calendar, isRange && styles.range, count > 1 && styles.multi, className)}
      onMouseLeave={isRange ? () => setHover(null) : undefined}
    >
      {Array.from({ length: count }, (_, i) => renderMonth(i))}
    </div>
  );
}

/*
 * Dates cross component boundaries as ISO calendar strings ("2026-09-29"),
 * never Date objects: a date of birth has no time zone, and a Date built at
 * night local time slides a day when it is serialised to UTC.
 */

export type IsoDate = string;

const MONTHS = [
  "January", "February", "March", "April", "May", "June",
  "July", "August", "September", "October", "November", "December",
];
const MONTHS_SHORT = ["Jan", "Feb", "Mar", "Apr", "May", "Jun", "Jul", "Aug", "Sep", "Oct", "Nov", "Dec"];
const WEEKDAYS = ["Monday", "Tuesday", "Wednesday", "Thursday", "Friday", "Saturday", "Sunday"];

const pad = (n: number) => String(n).padStart(2, "0");

export function toIso(y: number, m: number, d: number): IsoDate {
  return `${y}-${pad(m)}-${pad(d)}`;
}

export function parseIso(iso: IsoDate): { y: number; m: number; d: number } {
  const [y, m, d] = iso.split("-").map(Number);
  return { y, m, d };
}

export function isValidIso(iso: string): boolean {
  if (!/^\d{4}-\d{2}-\d{2}$/.test(iso)) return false;
  const { y, m, d } = parseIso(iso);
  return m >= 1 && m <= 12 && d >= 1 && d <= daysInMonth(y, m);
}

export function daysInMonth(y: number, m: number): number {
  return new Date(y, m, 0).getDate();
}

/** Today in the browser's zone. A function, so render stays free of `new Date()`. */
export function todayIso(): IsoDate {
  const now = new Date();
  return toIso(now.getFullYear(), now.getMonth() + 1, now.getDate());
}

export function addDays(iso: IsoDate, days: number): IsoDate {
  const { y, m, d } = parseIso(iso);
  const date = new Date(y, m - 1, d + days);
  return toIso(date.getFullYear(), date.getMonth() + 1, date.getDate());
}

/** Moves by months, clamping the day (31 Jan + 1 month = 28/29 Feb). */
export function addMonths(iso: IsoDate, months: number): IsoDate {
  const { y, m, d } = parseIso(iso);
  const total = y * 12 + (m - 1) + months;
  const ny = Math.floor(total / 12);
  const nm = (total % 12) + 1;
  return toIso(ny, nm, Math.min(d, daysInMonth(ny, nm)));
}

/** 0 = Monday … 6 = Sunday (ISO week). */
export function weekdayIndex(iso: IsoDate): number {
  const { y, m, d } = parseIso(iso);
  return (new Date(y, m - 1, d).getDay() + 6) % 7;
}

export function compareIso(a: IsoDate, b: IsoDate): number {
  return a < b ? -1 : a > b ? 1 : 0;
}

export function monthLabel(y: number, m: number): string {
  return `${MONTHS[m - 1]} ${y}`;
}

/** "24 Aug 2026": the display format used across the portal. */
export function formatDate(iso: IsoDate | null | undefined): string {
  if (!iso || !isValidIso(iso)) return "";
  const { y, m, d } = parseIso(iso);
  return `${d} ${MONTHS_SHORT[m - 1]} ${y}`;
}

/** "Monday 24 August 2026", for calendar cell labels. */
export function formatDateLong(iso: IsoDate): string {
  const { y, m, d } = parseIso(iso);
  return `${WEEKDAYS[weekdayIndex(iso)]} ${d} ${MONTHS[m - 1]} ${y}`;
}

/** "24/08/2026", the typed-entry format. */
export function formatDateInput(iso: IsoDate | null | undefined): string {
  if (!iso || !isValidIso(iso)) return "";
  const { y, m, d } = parseIso(iso);
  return `${pad(d)}/${pad(m)}/${y}`;
}

/** Accepts D/M/YYYY with / . - or space separators. Two-digit years are refused. */
export function parseDateInput(text: string): IsoDate | null {
  const match = text.trim().match(/^(\d{1,2})[/.\-\s](\d{1,2})[/.\-\s](\d{4})$/);
  if (!match) return null;
  const iso = toIso(Number(match[3]), Number(match[2]), Number(match[1]));
  return isValidIso(iso) ? iso : null;
}

/** Whole years between two ISO dates: age at a date. */
export function yearsBetween(from: IsoDate, to: IsoDate): number {
  const a = parseIso(from);
  const b = parseIso(to);
  let years = b.y - a.y;
  if (b.m < a.m || (b.m === a.m && b.d < a.d)) years -= 1;
  return years;
}

export const WEEKDAY_SHORT = ["Mo", "Tu", "We", "Th", "Fr", "Sa", "Su"];
export const WEEKDAY_NAMES = WEEKDAYS;
export const MONTH_NAMES: ReadonlyArray<string> = MONTHS;
export const MONTH_SHORT: ReadonlyArray<string> = MONTHS_SHORT;

.root {
  display: flex;
  flex-direction: column;
  gap: 6px;
  max-width: 240px;
}

.input {
  font-variant-numeric: tabular-nums;
  letter-spacing: 0.02em;
}

.open {
  border-color: var(--field-focus-border, rgba(var(--rgb-brand), 0.7));
  box-shadow: var(--field-focus-ring, var(--focus-halo));
}

.toggle {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 32px;
  height: 32px;
  margin-right: 5px;
  border: 0;
  border-radius: var(--r-xs);
  background: transparent;
  color: var(--ink-muted);
  transition:
    color var(--dur) var(--ease),
    background-color var(--dur) var(--ease);
}

.toggle:hover:not(:disabled),
.toggle[aria-expanded="true"] {
  color: var(--ink-brand);
  background: var(--wash-subtle);
}

/* Inside the focused box: an inset ring, clear of the box's own edge. */
.toggle:focus-visible {
  outline: none;
  box-shadow: inset 0 0 0 2px var(--field-focus-border, var(--focus-color));
}

.toggle:disabled {
  cursor: not-allowed;
  color: var(--ink-disabled);
}

.problem {
  display: flex;
  align-items: flex-start;
  gap: 6px;
  font-size: 12.5px;
  font-weight: 700;
  line-height: 1.4;
  color: var(--danger-ink);
}

.problem svg {
  margin-top: 1px;
  flex-shrink: 0;
}

.popup {
  position: fixed;
  z-index: var(--z-popover);
  padding: 14px;
  background: var(--surface-solid);
  border: 1px solid var(--line);
  border-radius: var(--r-xl);
  box-shadow: var(--shadow-float);
  animation: pop-in var(--dur) var(--ease-out);
}

@keyframes pop-in {
  from {
    opacity: 0;
    transform: translateY(-4px);
  }
}

/* Inline: the calendar shown open under the field, in flow, for docs and
   thumbnails. */
.rootInline {
  display: inline-flex;
  max-width: none;
  flex-direction: column;
  gap: 6px;
}

.popupInline[class] {
  position: static;
  animation: none;
}

"use client";

import { useEffect, useId, useLayoutEffect, useRef, useState, type KeyboardEvent } from "react";
import { cx } from "../_internal/cx";
import { Portal } from "../_internal/portal";
import { placePopup } from "../_internal/position";
import { mergeDescribedBy, useField } from "../Field/Field";
import { IconAlertCircle, IconCalendar } from "../Icon/Icon";
import boxStyles from "../TextInput/TextInput.module.css";
import { Calendar } from "./Calendar";
import { addMonths, compareIso, formatDateInput, parseDateInput, parseIso, todayIso, type IsoDate } from "./date-utils";
import styles from "./DateField.module.css";

export type DateFieldProps = {
  value: IsoDate | null;
  /** null when cleared or when the typed text is not a usable date. */
  onChange: (value: IsoDate | null) => void;
  isDateDisabled?: (date: IsoDate) => boolean;
  min?: IsoDate;
  max?: IsoDate;
  /** Month the calendar opens on when empty. For a date of birth, pass ~40 years ago (or use preset="dob"). */
  defaultMonth?: IsoDate;
  /**
   * dob: a date of birth, set up as a sign-up form does it. Month
   * and Year dropdowns in the calendar, years 1920 to this year, no future
   * dates, and an empty field opens 40 years back. Any prop passed explicitly
   * wins over the preset.
   */
  preset?: "dob";
  /** The calendar's caption. dropdown gives Month ▾ and Year ▾ quick pickers; see Calendar. */
  captionLayout?: "label" | "dropdown";
  /** Year span of the Year picker (dropdown caption only). */
  fromYear?: number;
  toYear?: number;
  invalid?: boolean;
  disabled?: boolean;
  required?: boolean;
  id?: string;
  name?: string;
  placeholder?: string;
  "aria-label"?: string;
  className?: string;
  /**
   * Show the calendar open, in place under the field: no portal, no focus
   * move, no outside-click listener. For docs and thumbnails.
   */
  inline?: boolean;
};

/** Earliest year the dob preset lists. 1920 covers anyone alive today. */
const DOB_FIRST_YEAR = 1920;
/** An empty date of birth opens here: about the middle of the adult range. */
const DOB_OPENS_YEARS_BACK = 40;

/**
 * Typed entry (DD/MM/YYYY) with a calendar popup. Typing is the fast path for
 * a date of birth decades back; the calendar is there for recent dates. Text
 * is parsed on blur, and an unusable entry is kept on screen with a reason
 * rather than silently wiped.
 */
export function DateField({
  value,
  onChange,
  isDateDisabled,
  min,
  max: maxProp,
  defaultMonth: defaultMonthProp,
  preset,
  captionLayout: captionLayoutProp,
  fromYear: fromYearProp,
  toYear: toYearProp,
  invalid: invalidProp,
  disabled,
  required,
  id: idProp,
  name,
  placeholder = "DD/MM/YYYY",
  "aria-label": ariaLabel,
  className,
  inline = false,
}: DateFieldProps) {
  const field = useField();
  const autoId = useId();
  const id = idProp ?? field?.id ?? `date-${autoId}`;
  const problemId = `${id}-format`;

  const [draft, setDraft] = useState(formatDateInput(value));
  const [synced, setSynced] = useState<IsoDate | null>(value);
  const [problem, setProblem] = useState<string | null>(null);
  const [openState, setOpen] = useState(false);
  const open = inline || openState;

  // The dob preset fills in whatever the caller left unset.
  const [today] = useState(todayIso);
  const dob = preset === "dob";
  const max = maxProp ?? (dob ? today : undefined);
  const defaultMonth = defaultMonthProp ?? (dob ? addMonths(today, -12 * DOB_OPENS_YEARS_BACK) : undefined);
  const captionLayout = captionLayoutProp ?? (dob ? "dropdown" : "label");
  const fromYear = fromYearProp ?? (dob ? DOB_FIRST_YEAR : undefined);
  const toYear = toYearProp ?? (dob ? parseIso(today).y : undefined);

  // Adopt a new value from the parent (a reset, a prefill) without an effect.
  if (value !== synced) {
    setSynced(value);
    setDraft(formatDateInput(value));
    setProblem(null);
  }

  const boxRef = useRef<HTMLDivElement>(null);
  const toggleRef = useRef<HTMLButtonElement>(null);
  const popupRef = useRef<HTMLDivElement>(null);
  const invalid = invalidProp ?? (Boolean(field?.invalid) || Boolean(problem));

  const reason = (iso: IsoDate): string | null => {
    if (min && compareIso(iso, min) < 0) return `Enter a date on or after ${formatDateInput(min)}.`;
    if (max && compareIso(iso, max) > 0) return `Enter a date on or before ${formatDateInput(max)}.`;
    if (isDateDisabled?.(iso)) return "That date can't be chosen.";
    return null;
  };

  const commitText = () => {
    const text = draft.trim();
    if (!text) {
      setProblem(null);
      if (value !== null) {
        setSynced(null);
        onChange(null);
      }
      return;
    }
    const iso = parseDateInput(text);
    const why = iso ? reason(iso) : "Enter the date as DD/MM/YYYY.";
    if (!iso || why) {
      setProblem(why);
      // Report the field as empty, but keep the typed text for correcting.
      setSynced(null);
      if (value !== null) onChange(null);
      return;
    }
    setProblem(null);
    setDraft(formatDateInput(iso));
    setSynced(iso);
    if (iso !== value) onChange(iso);
  };

  const pick = (iso: IsoDate) => {
    setProblem(null);
    setDraft(formatDateInput(iso));
    setSynced(iso);
    onChange(iso);
    setOpen(false);
    if (!inline) toggleRef.current?.focus();
  };

  const closePopup = (returnFocus: boolean) => {
    setOpen(false);
    if (returnFocus) toggleRef.current?.focus();
  };

  useLayoutEffect(() => {
    if (!open || inline) return;
    const box = boxRef.current;
    const popup = popupRef.current;
    if (!box || !popup) return;
    const place = () => placePopup(box, popup, { align: "start" });
    place();
    window.addEventListener("resize", place);
    window.addEventListener("scroll", place, true);
    return () => {
      window.removeEventListener("resize", place);
      window.removeEventListener("scroll", place, true);
    };
  }, [open, inline]);

  useEffect(() => {
    if (!open || inline) return;
    const onPointerDown = (e: PointerEvent) => {
      const target = e.target as Node;
      if (boxRef.current?.contains(target) || popupRef.current?.contains(target)) return;
      setOpen(false);
    };
    document.addEventListener("pointerdown", onPointerDown);
    return () => document.removeEventListener("pointerdown", onPointerDown);
  }, [open, inline]);

  const onPopupKeyDown = (e: KeyboardEvent<HTMLDivElement>) => {
    if (e.key === "Escape") {
      // Stop here so an enclosing Modal stays open.
      e.preventDefault();
      e.stopPropagation();
      closePopup(true);
    }
  };

  const popup = (
      <div
        ref={popupRef}
        role="dialog"
        aria-label="Choose date"
        className={cx(styles.popup, inline && styles.popupInline)}
        onKeyDown={onPopupKeyDown}
      >
        <Calendar
          value={value}
          onChange={pick}
          isDateDisabled={isDateDisabled}
          min={min}
          max={max}
          defaultMonth={defaultMonth}
          captionLayout={captionLayout}
          fromYear={fromYear}
          toYear={toYear}
          autoFocus={!inline}
        />
      </div>
  );

  return (
    <div data-slot="date-field" className={cx(styles.root, inline && styles.rootInline, className)}>
      <div
        ref={boxRef}
        className={cx(boxStyles.box, boxStyles.md, invalid && boxStyles.invalid, disabled && boxStyles.disabled, open && styles.open)}
      >
        <input
          id={id}
          name={name}
          type="text"
          inputMode="numeric"
          autoComplete="off"
          className={cx(boxStyles.input, styles.input)}
          placeholder={placeholder}
          value={draft}
          disabled={disabled}
          required={required ?? field?.required}
          aria-label={ariaLabel}
          aria-invalid={invalid || undefined}
          aria-describedby={mergeDescribedBy(field?.describedBy, problem ? problemId : undefined)}
          onChange={(e) => setDraft(e.target.value)}
          onBlur={commitText}
          onKeyDown={(e) => {
            if (e.key === "Enter") {
              e.preventDefault();
              commitText();
            } else if (e.key === "ArrowDown" && e.altKey) {
              e.preventDefault();
              setOpen(true);
            }
          }}
        />
        <button
          ref={toggleRef}
          type="button"
          className={styles.toggle}
          onClick={() => {
            if (inline) return;
            if (open) closePopup(false);
            else setOpen(true);
          }}
          disabled={disabled}
          aria-label={open ? "Close calendar" : "Choose date from calendar"}
          aria-haspopup="dialog"
          aria-expanded={open}
        >
          <IconCalendar size={16} />
        </button>
      </div>

      {problem ? (
        <p id={problemId} className={styles.problem}>
          <IconAlertCircle size={14} />
          <span>{problem}</span>
        </p>
      ) : null}

      {open ? (inline ? popup : <Portal>{popup}</Portal>) : null}
    </div>
  );
}
